rollback.sql:
DO $$ BEGIN
    LOCK TABLE clinlims.micro_case IN ACCESS EXCLUSIVE MODE;
    LOCK TABLE clinlims.micro_case_requested_test IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM clinlims.micro_case WHERE stage = 'CANCELLED') THEN
        RAISE EXCEPTION 'Cannot discard cancelled case state';
    END IF;
    IF EXISTS (SELECT 1 FROM clinlims.micro_case_requested_test) THEN
        RAISE EXCEPTION 'Cannot discard recorded requested-test case ownership';
    END IF;
END $$;
